# Writes data/ATTESTATION_STATUS.md and data/ATTESTATION_STATUS.json from the verified evidence and the glossary.
import csv, collections, json
with open('VISASTACK_PLATFORM_LANGUAGE_EVIDENCE.csv', encoding='utf-8') as fh:
    ev = list(csv.DictReader(fh))
with open('data/BN_BD_CORE_GLOSSARY.csv', encoding='utf-8') as fh:
    gl = list(csv.DictReader(fh))
ATTESTED = ('OFFICIAL_STRING_RESOURCE', 'DIRECT_SCREEN', 'BILINGUAL_OFFICIAL_PAGE')
att = [r for r in ev if r['evidence_quality'] in ATTESTED]
by_src = collections.defaultdict(lambda: collections.Counter())
for r in ev:
    by_src[r['platform']][r['evidence_quality'] + (' / ' + r['intent_match'] if r['intent_match'] else '')] += 1
cls = collections.Counter(t['attestation_class'] for t in gl)
exact_rows = sum(1 for r in att if r['intent_match'] == 'EXACT')
S = {
    'evidence_rows': len(ev), 'attested_rows': len(att), 'attested_exact_intent': exact_rows,
    'firefox_rows': sum(1 for r in att if r['platform'] == 'Firefox'), 'google_rows': sum(1 for r in att if r['platform'] == 'Google'),
    'firefox_bn': sum(1 for r in att if r['platform'] == 'Firefox' and r['locale'] == 'bn'), 'firefox_bn_BD': sum(1 for r in att if r['platform'] == 'Firefox' and r['locale'] == 'bn-BD'),
    'glossary': dict(cls), 'direct_or_bilingual_bangladeshi': 0,
}
with open('data/ATTESTATION_STATUS.json', 'w', encoding='utf-8') as out:
    json.dump(S, out, indent=1)
GAPS = [
    ('Facebook / Meta Bengali login and account labels', 'facebook.com and bn-in.facebook.com: no connection through the session proxy (HTTP 000) on 2026-11-12, curl and web-fetch tools', 'Needs the host allowed, or a person with the live product'),
    ('bKash EN/Bangla public navigation', 'bkash.com/bn: no connection (HTTP 000)', 'Same'),
    ('Pathao Bengali help and tracking', 'pathao.com: no connection (HTTP 000)', 'Same'),
    ('myGov Bangladesh forms (save vs submit, documents)', 'mygov.bd: no connection (HTTP 000). One row exists from a search summary only (citizen login), kept as CONTEXTUAL_ANALOGY', 'Same'),
    ('Bangladesh e-Passport application and status', 'epassport.gov.bd: no connection (HTTP 000)', 'Same'),
    ('Google Drive sharing and privacy (Bengali)', 'drive.google.com not in the allowed domains; support.google.com no connection (HTTP 000). Only the signed-out Google Accounts pages were readable', 'Same'),
    ('Microsoft Terminology (Bengali)', 'Terminology search returned 403 to curl; learn.microsoft.com is reachable but only English pages were found; no Bangla (Bangladesh) style guide is published there (a Bangla (India) guide is listed but was not reachable)', 'A downloadable terminology export would close this'),
]
L = ['# Attestation status: what was observed, what was recommended, what was never verified', '',
     'Generated by `tools/attestation-report.py` from `VISASTACK_PLATFORM_LANGUAGE_EVIDENCE.csv` and `data/BN_BD_CORE_GLOSSARY.csv`. Nothing here was written from memory: every attested row was re-fetched and its Bengali text found in the source (`tools/evidence-verify.py`).', '',
     '## 1. The three kinds of wording in this work', '',
     '| Kind | What it means | Where it applies |', '|---|---|---|',
     f'| OBSERVED | The exact Bengali was read in a product string file or page source and found again on re-fetch. Only `OFFICIAL_STRING_RESOURCE`, `DIRECT_SCREEN` and `BILINGUAL_OFFICIAL_PAGE` rows count | {len(att)} evidence rows; {exact_rows} of them have English that matches the intent exactly |',
     f'| LANGUAGE-MODEL RECOMMENDATION | Proposed by a language model, not observed anywhere | {cls.get("LLM_RECOMMENDATION", 0)} of {len(gl)} glossary terms and every one of the register drafts (full sentences included) |',
     f'| NEVER VERIFIED | The source was named in the brief but could not be read | Facebook, bKash, Pathao, myGov, e-Passport, Google Drive, Microsoft Terminology (section 4) |', '',
     '## 2. What the observed rows actually are', '',
     f'- {S["firefox_rows"]} rows come from Mozilla Firefox string files (community Bengali localizations in `mozilla-l10n/firefox-l10n`): {S["firefox_bn_BD"]} in locale `bn-BD` and {S["firefox_bn"]} in generic `bn`. They are real product strings, but they are a browser, not a Bangladeshi service product, and they are short interface words.',
     f'- {S["google_rows"]} rows come from the signed-out Google Accounts pages served with `hl=bn` (generic Bengali, not region-specific). They reproduced when re-fetched with redirects followed.',
     '- Most observed rows are NOT the same meaning as the English intent they were gathered for. The `intent_match` column says so: `EXACT` (same English), `RELATED_CONTAINS_INTENT_WORDS` (same word inside a longer string) or `LOOSE`. Only `EXACT` rows are used to call a glossary term observed.',
     '- No observed row is a full sentence, a consent text, a legal sentence or a visa-requirement sentence. No Bangladeshi government, bank, ride or messaging product is observed.', '',
     '| Source | Rows by quality / intent match |', '|---|---|']
for p, c in sorted(by_src.items()):
    L.append(f'| {p} | ' + '; '.join(f'{k}: {v}' for k, v in sorted(c.items())) + ' |')
L += ['', '## 3. Glossary terms by how their wording was obtained', '',
      '| Class | Terms | Meaning |', '|---|---|---|',
      f'| OBSERVED_EXACT_FORM | {cls.get("OBSERVED_EXACT_FORM", 0)} | The proposed Bengali appears in a verified row whose English matches the intent exactly |',
      f'| OBSERVED_DIFFERENT_FORM | {cls.get("OBSERVED_DIFFERENT_FORM", 0)} | A verified exact-intent row uses different Bengali; the editor chooses |',
      f'| OBSERVED_RELATED_ONLY | {cls.get("OBSERVED_RELATED_ONLY", 0)} | Only similar or loose rows exist; not evidence for this meaning |',
      f'| LLM_RECOMMENDATION | {cls.get("LLM_RECOMMENDATION", 0)} | Nothing observed. This includes every state word (Saved, Submitted, Sent, Received, Reviewed, Accepted, Verified, Confirmed, Approved) and every file-safety, requirement-level, sharing, copy and legal term |', '',
      'Terms with an observed exact-intent form or a different observed form:', '', '| English | Proposed | Class | Observed |', '|---|---|---|---|']
for t in gl:
    if t['attestation_class'] in ('OBSERVED_EXACT_FORM', 'OBSERVED_DIFFERENT_FORM'):
        L.append(f"| {t['english']} | {t['bn_bd_proposed']} | {t['attestation_class'].replace('OBSERVED_', '')} | {t['observed_forms'][:90].replace('|', '/')} |")
L += ['', '## 4. Research gaps (inaccessible sources)', '', 'Attempted on 2026-11-12. No observation from these sources is claimed anywhere in this work.', '',
      '| Source named in the brief | Result | To close the gap |', '|---|---|---|']
for a, b, c in GAPS: L.append(f'| {a} | {b} | {c} |')
L += ['', '## 5. What this means for the register', '',
      'Every Bengali sentence in `VISASTACK_TRANSLATION_REGISTER.csv` is a language-model draft (`provenance` column). The register never calls a draft attested. Where a draft uses a glossary term, the term may be OBSERVED_EXACT_FORM (short words such as Save, Delete, Sign in, Password, Settings, Next, Cancel, Close, Try again, Learn more), but the surrounding sentence is not. Words with the highest product risk (the state words, file safety, requirement levels, sharing and legal hold) have no observation at all and rest on the guardrails and the owner as editor.', '']
with open('data/ATTESTATION_STATUS.md', 'w', encoding='utf-8') as out:
    out.write('\n'.join(L) + '\n')
print(json.dumps(S))
